def test_aggregators_max_min(self):
    table = hl.utils.range_table(10)
    for f, typ in [(lambda x: hl.int32(x), tint32), (lambda x: hl.int64(x), tint64), (lambda x: hl.float32(x), tfloat32), (lambda x: hl.float64(x), tfloat64)]:
        t = table.annotate(x=-1 * f(table.idx) - 5, y=hl.missing(typ))
        r = t.aggregate(hl.struct(max=hl.agg.max(t.x), max_empty=hl.agg.max(t.y), min=hl.agg.min(t.x), min_empty=hl.agg.min(t.y)))
        self.assertTrue(r.max == -5 and r.max_empty is None and (r.min == -14) and (r.min_empty is None))

def test_aggregators_sum_product(self):
    table = hl.utils.range_table(5)
    for f, typ in [(lambda x: hl.int32(x), tint32), (lambda x: hl.int64(x), tint64), (lambda x: hl.float32(x), tfloat32), (lambda x: hl.float64(x), tfloat64)]:
        t = table.annotate(x=-1 * f(table.idx) - 1, y=f(table.idx), z=hl.missing(typ))
        r = t.aggregate(hl.struct(sum_x=hl.agg.sum(t.x), sum_y=hl.agg.sum(t.y), sum_empty=hl.agg.sum(t.z), prod_x=hl.agg.product(t.x), prod_y=hl.agg.product(t.y), prod_empty=hl.agg.product(t.z)))
        self.assertTrue(r.sum_x == -15 and r.sum_y == 10 and (r.sum_empty == 0) and (r.prod_x == -120) and (r.prod_y == 0) and (r.prod_empty == 1))

